// "Reading the territory": the narrative generated by the storytelling service, shown above the
// cards. Each figure carries the colour of its scale, like the chips on the cards, and hovering
// a sentence highlights the card that shows its data.

import { el } from './charts.js';
import { t } from './i18n.js';

const CARD_OF_FACT = {
  residents: 'tiles',
  sewage: 't-environment',
  precarious: 't-environment',
  garbage: 't-environment',
  dengue: 't-environment',
  lepto: 't-environment',
  crowding: 't-respiratory',
  crowded: 't-respiratory',
  tb: 't-respiratory',
  tb_district: 't-respiratory',
  access: 't-access',
  network: 'nearby-types',
  teen: 't-maternal',
  teen_district: 't-maternal',
  preterm: 't-maternal',
  mortality: 't-mortality',
};

/** The fact a sentence is about: its own, or the one its caveat is attached to. */
function sentenceFact(sentence, caveats) {
  if (sentence.facts.length) return sentence.facts[0];
  const rule = sentence.caveats[0];
  return caveats.find((c) => c.rule === rule)?.fact;
}

function highlight(fact, on) {
  const card = document.getElementById(CARD_OF_FACT[fact]);
  card?.classList.toggle('is-linked', on);
}

function renderSentence(sentence, caveats) {
  const fact = sentenceFact(sentence, caveats);
  const node = el('span', { class: 'narrative-sentence', dataset: { fact: fact || '' } },
    sentence.segments.map((segment) => (segment.scope
      ? el('span', { class: `scope-inline scope-${segment.scope}`, title: t(`narrative.scope.${segment.scope}`), text: segment.text })
      : segment.text)),
    ' ');
  if (CARD_OF_FACT[fact]) {
    node.addEventListener('mouseenter', () => highlight(fact, true));
    node.addEventListener('mouseleave', () => highlight(fact, false));
  }
  return node;
}

function provenance(body) {
  const planned = body.facts.filter((f) => f.planned);
  const rows = planned.map((f) => el('tr', {},
    el('td', { text: f.id }),
    el('td', { text: Object.entries(f.slots)
      .filter(([, slot]) => slot.scope && 'value' in slot)
      .map(([field, slot]) => `${field}: ${slot.text}`)
      .join(' · ') }),
    el('td', { class: 'numeric', text: f.importance.toFixed(2) })));
  const rules = body.caveats.map((c) => el('li', {
    text: t('narrative.rule', { rule: c.rule, note: c.note, effect: t(`narrative.effect.${c.effect}`), fact: c.fact }),
  }));
  return el('details', { class: 'narrative-how' },
    el('summary', { text: t('narrative.how') }),
    el('p', { class: 'hint', text: t('narrative.method', { version: body.version }) }),
    el('table', { class: 'narrative-facts' },
      el('thead', {}, el('tr', {},
        el('th', { text: t('narrative.fact') }), el('th', { text: t('narrative.values') }), el('th', { text: t('narrative.importance') }))),
      el('tbody', {}, rows)),
    rules.length ? el('ul', { class: 'narrative-rules' }, rules) : null,
    el('p', { class: 'hint', text: body.verified ? t('narrative.verified') : t('narrative.unverified') }));
}

export function renderNarrative(container, body) {
  container.replaceChildren(
    el('h3', { class: 'card-title', text: t('narrative.title') }),
    ...body.paragraphs.map((paragraph) => el('p', { class: 'narrative-text' },
      paragraph.map((sentence) => renderSentence(sentence, body.caveats)))),
    el('p', { class: 'hint', text: t('narrative.auto') }),
    provenance(body));
  container.hidden = false;
}

export function renderNarrativeState(container, key) {
  container.replaceChildren(
    el('h3', { class: 'card-title', text: t('narrative.title') }),
    el('p', { class: 'hint', text: t(key) }));
  container.hidden = false;
}
